  async function loadMatchSeekers(workshopId) {
    if (!workshopId) {
      setMatchSeekers([]);
      return;
    }

    setMatchSeekersLoading(true);
    try {
      const { data, error } = await matchingDb.rpc("admin_get_workshop_seekers", {
        p_workshop_id: Number(workshopId)
      });
      if (error) throw error;
      setMatchSeekers(data || []);
      setMatchForm(prev => ({
        ...prev,
        seekerUserId: (data || []).some(x => x.user_id === prev.seekerUserId)
          ? prev.seekerUserId
          : ""
      }));
    } catch (error) {
      console.error("Suchende für Vermittlung konnten nicht geladen werden:", error);
      setMatchSeekers([]);
      alert("Die Suchenden konnten nicht geladen werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setMatchSeekersLoading(false);
    }
  }

  async function matchWorkshopSeekerWithGuest() {
    if (readOnly || matchBusy) return;

    const workshopId = Number(matchForm.workshopId);
    const seekerUserId = matchForm.seekerUserId;
    const partnerName = matchForm.partnerName.trim();
    const partnerEmail = matchForm.partnerEmail.trim();

    const seeker = matchSeekers.find(x => x.user_id === seekerUserId);

    if (!workshopId || !seekerUserId || !seeker || !partnerName) {
      alert("Bitte Workshop, eine suchende Person und den Namen des Tanzpartners auswählen bzw. angeben.");
      return;
    }

    if (!window.confirm(
      `${seeker.display_name || "Die suchende Person"} mit „${partnerName}“ für diesen Workshop zusammenführen?\n\n` +
      `Die aktive Tanzpartnersuche wird dabei beendet und eine Workshop-Paaranmeldung angelegt.`
    )) return;

    setMatchBusy(true);
    try {
      const { data: registrationId, error } = await matchingDb.rpc("admin_match_workshop_seeker_guest", {
        p_workshop_id: workshopId,
        p_seeker_user_id: seekerUserId,
        p_partner_name: partnerName,
        p_partner_email: partnerEmail || null
      });

      if (error) throw error;

      const workshop = workshops.find(w => Number(w.id) === workshopId);
      const seekerEmail = seeker.email || "";
      let mailWarning = "";

      if (!trainingModeActive && (seekerEmail || partnerEmail)) {
        const mailResult = await sendWorkshopPairConfirmation({
          workshopId,
          registrationId,
          user1Name: seeker.display_name || "Tanzpartner-Suchende Person",
          user1Email: seekerEmail,
          user2Name: partnerName,
          user2Email: partnerEmail,
          costPerPerson: workshop?.cost_per_person ?? null
        });
        if (!mailResult.ok) {
          mailWarning = "\n\n⚠️ Die Paaranmeldung wurde gespeichert, aber die Bestätigungs-Mail konnte nicht vollständig versendet werden.";
        }
      }

      setMatchSeekers(prev => prev.filter(x => x.user_id !== seekerUserId));
      setMatchForm({
        workshopId: String(workshopId),
        seekerUserId: "",
        partnerName: "",
        partnerEmail: ""
      });

      await Promise.all([loadWorkshopRegistrations(), loadRecurringSeekers()]);
      alert(
        `🤝 ${seeker.display_name || "Die Person"} wurde erfolgreich mit „${partnerName}“ zusammengeführt.` +
        mailWarning
      );
    } catch (error) {
      console.error("Tanzpartnervermittlung fehlgeschlagen:", error);
      alert("Die Vermittlung konnte nicht gespeichert werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setMatchBusy(false);
    }
  }

  async function reviewAutomaticMatchProposal(proposalId, approve) {
    if (readOnly || automaticMatchReviewBusy) return;
    setAutomaticMatchReviewBusy(String(proposalId));
    try {
      if (trainingModeActive) {
        setAdminMatchProposals(prev => prev.map(p => String(p.id) === String(proposalId)
          ? { ...p, status: approve ? "pending" : "rejected" }
          : p
        ));
        setAutomaticMatchPendingCount(prev => Math.max(0, Number(prev || 0) - 1));
        alert(`🧪 ${approve ? "Freigabe" : "Ablehnung"} durchgeführt.\n\nDie Änderung wurde nur in der Demo-Übungsumgebung simuliert.`);
        return true;
      }
      const { data, error } = await matchingDb.rpc("admin_review_workshop_match_proposal", {
        p_proposal_id: proposalId,
        p_approve: !!approve
      });
      if (error) throw error;
      await loadAdminMatchProposals(registeredMatchWorkshopId || null);
      alert(approve
        ? "🤝 Vorschlag freigegeben. Beide Personen erhalten jetzt den Vermittlungsvorschlag."
        : "Vorschlag abgelehnt.");
      return data;
    } catch (error) {
      console.error("Automatischer Vermittlungsvorschlag konnte nicht geprüft werden:", error);
      alert("Der Vorschlag konnte nicht geprüft werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setAutomaticMatchReviewBusy("");
    }
  }

  async function loadAdminMatchProposals(workshopId = null) {
    setAdminMatchProposalsLoading(true);
    try {
      const [{ data, error }, { data: externalData, error: externalError }] = await Promise.all([
        matchingDb.rpc("admin_get_workshop_match_proposals", {
          p_workshop_id: workshopId ? Number(workshopId) : null
        }),
        matchingDb.rpc("admin_get_external_match_proposals", {
          p_workshop_id: workshopId ? Number(workshopId) : null
        })
      ]);
      if (error) throw error;
      if (externalError) throw externalError;
      const proposals = data || [];
      setAdminMatchProposals(proposals);
      setAutomaticMatchPendingCount(proposals.filter(p => p.status === "admin_review").length);
      setAdminExternalMatchProposals(externalData || []);
    } catch (error) {
      console.error("Vermittlungsvorschläge konnten nicht geladen werden:", error);
      setAdminMatchProposals([]);
    } finally {
      setAdminMatchProposalsLoading(false);
    }
  }


  // Chatstatus für Vermittlungen:
  // Immer den konkreten Nutzer-zu-Nutzer-Chat prüfen. Dadurch wird nicht
  // versehentlich "Noch kein persönlicher Chatkontakt" angezeigt, obwohl
  // bereits Nachrichten zwischen den beiden Personen existieren.
  async function loadMediationChatStatuses(proposals = adminMatchProposals, externalProposals = adminExternalMatchProposals) {
    const rows = [
      ...(proposals || []).map(p => ({
        key: `proposal:${p.id}`,
        workshopId: p.workshop_id,
        user1Id: p.user1_id,
        user2Id: p.user2_id
      })),
      ...(externalProposals || []).map(p => ({
        key: `external:${p.id}`,
        workshopId: p.workshop_id,
        user1Id: p.seeker_user_id || p.user_id || p.seeker_id,
        user2Id: null
      })),
      ...(contactRequests || []).filter(r => r.status === "pending" && r.workshop_id).map(r => ({
        key: `contact:${r.id}`,
        workshopId: r.workshop_id,
        user1Id: r.requester_id,
        user2Id: r.recipient_id
      }))
    ].filter(r => r.workshopId && r.user1Id);

    if (!rows.length) {
      setMediationChatStatus({});
      return;
    }

    // Wichtig: Jede Vermittlung bekommt ihren Status unabhängig von den
    // anderen. Früher wurde Promise.all() verwendet. Wenn nur eine
    // Supabase-Abfrage hängen blieb, blieben dadurch ALLE Karten dauerhaft
    // auf "Chatstatus wird geprüft …".
    const initial = {};
    rows.forEach(row => {
      initial[row.key] = row.user2Id
        ? "💬 Chatstatus wird geprüft …"
        : "💬 Externe Vermittlung – kein interner Chat";
    });
    setMediationChatStatus(initial);

    const withTimeout = (promise, ms = 8000) =>
      Promise.race([
        promise,
        new Promise((_, reject) =>
          setTimeout(() => reject(new Error("Chatstatus-Abfrage hat zu lange gedauert.")), ms)
        )
      ]);

    rows.forEach(async row => {
      if (!row.user2Id) return;

      try {
        const { data: chatRows, error: chatError } = await withTimeout(
          matchingDb.rpc("admin_get_pair_chat_status", {
            p_user1_id: row.user1Id,
            p_user2_id: row.user2Id
          })
        );

        if (chatError) throw chatError;

        const chat = Array.isArray(chatRows) ? chatRows[0] : chatRows;
        const total = Number(chat?.message_count || 0);
        const user1Messages = Number(chat?.user1_message_count || 0);
        const user2Messages = Number(chat?.user2_message_count || 0);

        let statusText;
        if (user1Messages > 0 && user2Messages > 0) {
          statusText = "💬 Persönlicher Chatkontakt vorhanden";
        } else if (user1Messages > 0) {
          statusText = "💬 Person 1 hat geschrieben · Antwort steht aus";
        } else if (user2Messages > 0) {
          statusText = "💬 Person 2 hat geschrieben · Antwort steht aus";
        } else if (total === 0) {
          statusText = "💬 Noch kein persönlicher Chatkontakt";
        } else {
          statusText = "💬 Persönlicher Chatkontakt vorhanden";
        }

        setMediationChatStatus(prev => ({
          ...prev,
          [row.key]: statusText
        }));
      } catch (rowError) {
        console.warn(
          "Chatstatus konnte für Vermittlung nicht geprüft werden:",
          row.key,
          rowError
        );
        setMediationChatStatus(prev => ({
          ...prev,
          [row.key]: "💬 Chatstatus konnte nicht geprüft werden"
        }));
      }
    });
  }

  async function openMediationChat(item) {
    if (!item?.user1Id || !item?.user2Id) {
      alert("Für Gastherren gibt es keinen internen Nutzer-Chat, den der Admin öffnen kann.");
      return;
    }

    setAdminChatViewerLoading(true);
    try {
      const { data: messages, error } = await matchingDb.rpc(
        "admin_get_pair_chat_messages",
        {
          p_user1_id: item.user1Id,
          p_user2_id: item.user2Id,
          p_workshop_id: item.workshopId ? Number(item.workshopId) : null
        }
      );
      if (error) throw error;

      const ids = [...new Set((messages || []).flatMap(m => [m.sender_id, m.recipient_id]).filter(Boolean))];
      let profileMap = {};
      if (ids.length) {
        const { data: profiles, error: profileError } = await adminDb
          .from("profiles")
          .select("id,display_name")
          .in("id", ids);
        if (profileError) throw profileError;
        profileMap = Object.fromEntries((profiles || []).map(profile => [profile.id, profile.display_name]));
      }

      setAdminChatViewer({ item, messages: messages || [], profileMap });
    } catch (error) {
      console.error("Admin-Chat konnte nicht geöffnet werden:", error);
      alert("Der Chat konnte nicht geöffnet werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setAdminChatViewerLoading(false);
    }
  }

  // Eine Vermittlung wird getrennt, ohne Nutzer oder Workshop-Anmeldung zu löschen.
  // Wichtig: Es wird bewusst KEIN updated_at auf workshop_match_proposals
  // geschrieben, weil diese Tabelle in älteren Projekten keine solche Spalte hat.
  async function separateMediation(item) {
    if (readOnly || separatingMediationKey) return;
    const key = item?.key || `${item?.workshopId}:${item?.user1Id}:${item?.user2Id}`;
    const workshopTitle = item?.workshopTitle || "diesem Workshop";
    const name1 = item?.user1Name || "Person 1";
    const name2 = item?.user2Name || "Person 2";

    if (!window.confirm(
      `Vermittlung ${name1} ↔ ${name2} für „${workshopTitle}“ wirklich trennen?\n\n` +
      `Die Workshop-Anmeldung bleibt bestehen. Nur die Tanzpartnerschaft/Vermittlung wird gelöst.`
    )) return;

    setSeparatingMediationKey(key);
    try {
      if (trainingModeActive) {
        setAdminMatchProposals(prev => (prev || []).filter(p => String(p.id) !== String(item.proposalId)));
        setAdminExternalMatchProposals(prev => (prev || []).filter(p => String(p.id) !== String(item.proposalId)));
        setAdminSelfFoundPairs(prev => (prev || []).filter(p => String(p.pair_id || p.id) !== String(item.pairId || item.id)));
        setMediationChatStatus(prev => {
          const next = { ...prev };
          delete next[key];
          return next;
        });
        alert(`🧪 Die Vermittlung ${name1} ↔ ${name2} wurde in der Demo getrennt.\n\nDie Live-Daten bleiben unverändert.`);
        return;
      }
      // 1. Tatsächliche Tanzpartnerschaft entfernen – workshop_pairs hat
      // bewusst KEINE id-Spalte. Deshalb immer über Workshop + beide User löschen.
      // Die workshop_registrations-Zeile bleibt ausdrücklich unangetastet.
      if (item.user1Id && item.user2Id && item.workshopId) {
        const ids = [String(item.user1Id), String(item.user2Id)];
        const { data: pairs, error: pairFindError } = await adminDb
          .from("workshop_pairs")
          .select("workshop_id,user1_id,user2_id")
          .eq("workshop_id", item.workshopId);
        if (pairFindError) throw pairFindError;

        const match = (pairs || []).find(p => {
          const pids = [String(p.user1_id), String(p.user2_id)];
          return pids.includes(ids[0]) && pids.includes(ids[1]);
        });
        if (match) {
          const { error } = await adminDb
            .from("workshop_pairs")
            .delete()
            .eq("workshop_id", item.workshopId)
            .eq("user1_id", match.user1_id)
            .eq("user2_id", match.user2_id);
          if (error) throw error;
        }
      }

      // 2. Offene/angenommene Kontaktanfrage beenden, damit die alte
      // Vermittlung nicht sofort wieder als aktiv erscheint.
      if (item.user1Id && item.user2Id && item.workshopId) {
        const { data: contacts, error: contactFindError } = await adminDb
          .from("contact_requests")
          .select("id,requester_id,recipient_id,status")
          .eq("workshop_id", item.workshopId);
        if (contactFindError) throw contactFindError;

        const contact = (contacts || []).find(c => {
          const ids = [String(c.requester_id), String(c.recipient_id)];
          return ids.includes(String(item.user1Id)) && ids.includes(String(item.user2Id));
        });
        if (contact?.id && ["pending", "accepted"].includes(contact.status)) {
          const { error } = await adminDb
            .from("contact_requests")
            .update({ status: "cancelled" })
            .eq("id", contact.id);
          if (error) throw error;
        }
      }

      // 3. Einen zugehörigen Vermittlungsvorschlag wirklich löschen.
      // Direktes DELETE aus dem Browser kann durch RLS blockiert werden.
      // Deshalb erfolgt die Löschung sicher über die Admin-RPC.
      if (item.proposalId) {
        const { data: deleted, error: proposalDeleteError } = await matchingDb.rpc(
          "admin_delete_workshop_match_proposal",
          { p_proposal_id: item.proposalId }
        );
        if (proposalDeleteError) throw proposalDeleteError;
        if (deleted !== true) {
          throw new Error("Der Vermittlungsvorschlag konnte nicht entfernt werden.");
        }
      }

      await Promise.all([
        loadAdminSelfFoundPairs(),
        loadAdminMatchProposals(null),
        loadContactRequests()
      ]);
      // Bereits geöffnete Vermittlungsauswahlen direkt aktualisieren.
      if (String(registeredMatchWorkshopId) === String(item.workshopId)) {
        await loadRegisteredMatchSeekers(item.workshopId);
      }
      if (String(externalSelectedWorkshopId) === String(item.workshopId)) {
        await loadExternalMatchSeekers(item.workshopId);
      }
      alert(`✅ Die Vermittlung ${name1} ↔ ${name2} wurde getrennt.\n\nDie Workshop-Anmeldung und die Nutzer bleiben erhalten.`);
    } catch (error) {
      console.error("Vermittlung konnte nicht getrennt werden:", error);
      alert("❌ Die Vermittlung konnte nicht getrennt werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setSeparatingMediationKey("");
    }
  }

  useEffect(() => {
    if (view !== "matching") return;
    loadMediationChatStatuses();
  }, [view, adminMatchProposals, adminExternalMatchProposals, contactRequests]);

  async function loadRegisteredMatchSeekers(workshopId) {
    if (!workshopId) {
      setRegisteredMatchSeekers([]);
      setRegisteredMatchUser1Id("");
      setRegisteredMatchUser2Id("");
      return;
    }

    setRegisteredMatchSeekersLoading(true);
    try {
      const [{ data: seekers, error: seekerError }, { data: pairs, error: pairError }] =
        await Promise.all([
          matchingDb.rpc("admin_get_workshop_seekers", { p_workshop_id: Number(workshopId) }),
          matchingDb.from("workshop_pairs").select("user1_id,user2_id").eq("workshop_id", Number(workshopId))
        ]);

      if (seekerError) throw seekerError;
      if (pairError) throw pairError;

      // Eine erhalten gebliebene Workshop-Anmeldung bedeutet nicht zwingend,
      // dass die Vermittlung noch aktiv ist. Nach „Vermittlung trennen“ bleibt
      // die Anmeldung bestehen; deshalb sperren nur aktive workshop_pairs.
      const pairedIds = new Set(
        (pairs || []).flatMap(r => [r.user1_id, r.user2_id]).filter(Boolean).map(String)
      );

      const openSeekers = (seekers || []).filter(person => !pairedIds.has(String(person.user_id)));

      setRegisteredMatchSeekers(openSeekers);
      setRegisteredMatchUser1Id(prev => openSeekers.some(x => String(x.user_id) === String(prev)) ? prev : "");
      setRegisteredMatchUser2Id(prev => openSeekers.some(x => String(x.user_id) === String(prev)) ? prev : "");
    } catch (error) {
      console.error("Offene Tanzpartnersuchen konnten nicht geladen werden:", error);
      setRegisteredMatchSeekers([]);
      setRegisteredMatchUser1Id("");
      setRegisteredMatchUser2Id("");
      alert("Die offenen Tanzpartnersuchen konnten nicht geladen werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setRegisteredMatchSeekersLoading(false);
    }
  }

  async function mediateRegisteredSeekers() {
    if (readOnly || registeredMatchBusy) return;

    const workshopId = Number(registeredMatchWorkshopId);
    const user1 = registeredMatchSeekers.find(x => String(x.user_id) === String(registeredMatchUser1Id));
    const user2 = registeredMatchSeekers.find(x => String(x.user_id) === String(registeredMatchUser2Id));

    if (!workshopId || !user1 || !user2 || String(user1.user_id) === String(user2.user_id)) {
      alert("Bitte Workshop und zwei unterschiedliche offene Tanzpartnersuchende auswählen.");
      return;
    }

    const workshop = workshops.find(w => Number(w.id) === workshopId);
    const name1 = user1.display_name || "Tanzpartner-Suchende Person";
    const name2 = user2.display_name || "Tanzpartner-Suchende Person";

    if (!window.confirm(
      `${name1} und ${name2} für „${workshop?.title || "diesen Workshop"}“ vorschlagen?\n\n` +
      `Beide Personen erhalten einen Vermittlungsvorschlag. Eine Annahme genügt, um die Tanzpartnerschaft und die Workshop-Anmeldung anzulegen. Bei Ablehnung bleibt die Tanzpartnersuche offen.`
    )) return;

    setRegisteredMatchBusy(true);
    try {
      if (trainingModeActive) {
        const proposalId = `training-proposal-${Date.now()}`;
        setAdminMatchProposals(prev => [{
          id: proposalId,
          workshop_id: workshopId,
          user1_id: user1.user_id,
          user2_id: user2.user_id,
          user1_name: name1,
          user2_name: name2,
          status: "pending",
          user1_response: "pending",
          user2_response: "pending",
          created_at: new Date().toISOString(),
          workshop_title: workshop?.title || `Workshop ${workshopId}`
        }, ...(prev || [])]);
        setRegisteredMatchSeekers(prev => (prev || []).filter(x => ![String(user1.user_id), String(user2.user_id)].includes(String(x.user_id))));
        setRegisteredMatchUser1Id("");
        setRegisteredMatchUser2Id("");
        alert(`🧪 Vermittlungsvorschlag erstellt.\n\n${name1} ↔ ${name2}\n\nDie Änderung wurde nur in der Demo-Übungsumgebung simuliert.`);
        return proposalId;
      }

      const { data: proposalId, error } = await matchingDb.rpc("admin_create_workshop_match_proposal", {
        p_workshop_id: workshopId,
        p_user1_id: user1.user_id,
        p_user2_id: user2.user_id
      });
      if (error) throw error;

      setRegisteredMatchUser1Id("");
      setRegisteredMatchUser2Id("");
      await Promise.all([
        loadRegisteredMatchSeekers(workshopId),
        loadAdminMatchProposals(workshopId)
      ]);

      alert(`🤝 Vermittlungsvorschlag gesendet.\n\n${name1} und ${name2} müssen jetzt jeweils selbst annehmen.`);
      return proposalId;
    } catch (error) {
      console.error("Vermittlungsvorschlag konnte nicht erstellt werden:", error);
      alert("Der Vermittlungsvorschlag konnte nicht erstellt werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setRegisteredMatchBusy(false);
    }
  }

  async function loadExternalDancers() {
    setExternalDancersLoading(true);
    setExternalAvailabilityLoading(true);
    try {
      const [{ data: dancers, error: dancerError }, { data: availability, error: availabilityError }] =
        await Promise.all([
          matchingDb.rpc("admin_get_external_dancers"),
          matchingDb.rpc("admin_get_external_availability")
        ]);

      if (dancerError) throw dancerError;
      if (availabilityError) throw availabilityError;

      setExternalDancers(dancers || []);
      setExternalAvailability(availability || []);
    } catch (error) {
      console.error("Gastherren konnten nicht geladen werden:", error);
      setExternalDancers([]);
      setExternalAvailability([]);
      alert("Die Gastherren konnten nicht geladen werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setExternalDancersLoading(false);
      setExternalAvailabilityLoading(false);
    }
  }

  async function copyExternalStatusLink(dancer) {
    if (!dancer?.id) return;
    try {
      const { data: token, error } = await matchingDb.rpc("admin_get_external_status_token", { p_external_dancer_id: dancer.id });
      if (error) throw error;
      if (!token) throw new Error("Für diesen Gastherren ist kein Status-Link vorhanden.");
      const url = `${window.location.origin}/?gastherren-status=${encodeURIComponent(token)}`;
      try {
        await navigator.clipboard.writeText(url);
        alert(`Status-Link für ${dancer.name || "den Gastherren"} wurde kopiert.\n\nDu kannst ihn jetzt per WhatsApp oder E-Mail weitergeben.`);
      } catch {
        window.prompt("Diesen persönlichen Status-Link kopieren und weitergeben:", url);
      }
    } catch (error) {
      console.error("Status-Link konnte nicht erstellt werden:", error);
      alert("Der Status-Link konnte nicht erstellt werden: " + (error?.message || "Unbekannter Fehler"));
    }
  }

  async function saveExternalDancer() {
    if (readOnly || externalDancerBusy) return;
    const name = externalDancerForm.name.trim();
    if (!name) {
      alert("Bitte einen Namen angeben.");
      return;
    }

    setExternalDancerBusy(true);
    try {
      if (trainingModeActive) {
        const existingId = externalDancerForm.id || `training-dancer-${Date.now()}`;
        const nextDancer = {
          id: existingId,
          name,
          email: externalDancerForm.email.trim(),
          phone: externalDancerForm.phone.trim(),
          notes: externalDancerForm.notes.trim(),
          gender: externalDancerForm.gender || "",
          height_cm: externalDancerForm.height_cm ? Number(externalDancerForm.height_cm) : null
        };
        setExternalDancers(prev => externalDancerForm.id
          ? (prev || []).map(d => String(d.id) === String(existingId) ? { ...d, ...nextDancer } : d)
          : [nextDancer, ...(prev || [])]
        );
        setExternalDancerForm({ id: "", name: "", email: "", phone: "", gender: "", height_cm: "", notes: "" });
        alert(`🧪 Gastherr ${externalDancerForm.id ? "aktualisiert" : "vorgemerkt"}.\n\nDie Änderung wurde nur in der Demo-Übungsumgebung simuliert.`);
        return;
      }

      const { data: id, error } = await matchingDb.rpc("admin_save_external_dancer", {
        p_id: externalDancerForm.id || null,
        p_name: name,
        p_email: externalDancerForm.email.trim() || null,
        p_phone: externalDancerForm.phone.trim() || null,
        p_notes: externalDancerForm.notes.trim() || null,
        p_gender: externalDancerForm.gender || null,
        p_height_cm: externalDancerForm.height_cm ? Number(externalDancerForm.height_cm) : null
      });
      if (error) throw error;

      setExternalDancerForm({ id: "", name: "", email: "", phone: "", gender: "", height_cm: "", notes: "" });
      await loadExternalDancers();
      alert(externalDancerForm.id ? "Gastherr wurde aktualisiert. ✅" : "Gastherr wurde vorgemerkt. ✅");
    } catch (error) {
      console.error("Gastherr konnte nicht gespeichert werden:", error);
      alert("Der Gastherren konnte nicht gespeichert werden: " + (error?.message || "Unbekannter Fehler"));
    } finally {
      setExternalDancerBusy(false);
    }
  }

  async function deactivateExternalDancer(id, name) {
    if (readOnly || !id) return;
    if (!window.confirm(`„${name || "Dieser Gastherren"}“ wirklich aus dem verfügbaren Pool entfernen?`)) return;

    if (trainingModeActive) {
      setExternalDancers(prev => (prev || []).filter(d => String(d.id) !== String(id)));
      setExternalAvailability(prev => (prev || []).filter(a => String(a.external_dancer_id) !== String(id)));
      if (String(externalProposalDancerId) === String(id)) setExternalProposalDancerId("");
      alert(`🧪 ${name || "Der Gastherren"} wurde in der Demo aus dem Pool entfernt.\n\nDie Live-Daten bleiben unverändert.`);
      return;
    }

    try {
      const { data, error } = await matchingDb.rpc("admin_deactivate_external_dancer", { p_id: id });
      if (error) throw error;
      if (!data) throw new Error("Der Gastherren wurde nicht gefunden.");
      await loadExternalDancers();
      alert("Gastherr wurde aus dem Pool entfernt. ✅");
    } catch (error) {
      console.error("Gastherr konnte nicht entfernt werden:", error);
      alert("Der Gastherren konnte nicht entfernt werden: " + (error?.message || "Unbekannter Fehler"));
    }
  }

  function getExternalDancersForWorkshop(workshopId) {
    const list = (externalDancers || []).filter(dancer =>
      externalAvailability.some(a =>
        String(a.external_dancer_id) === String(dancer.id) &&
        Number(a.workshop_id) === Number(workshopId) &&
        a.status === "available"
      )
    );

    return [...list].sort((a, b) => {
      if (externalProposalDancerSort === "name") {
        return String(a.name || "").localeCompare(String(b.name || ""), "de", { sensitivity: "base" });
      }
      const genderOrder = externalProposalDancerSort === "gender_mann"
        ? { Mann: 0, Frau: 1 }
        : { Frau: 0, Mann: 1 };
      const ga = genderOrder[a.gender] ?? 2;
      const gb = genderOrder[b.gender] ?? 2;
      if (ga !== gb) return ga - gb;
      return String(a.name || "").localeCompare(String(b.name || ""), "de", { sensitivity: "base" });
    });
  }

  function externalDancerLabel(dancer) {
    const gender = dancer?.gender || "Geschlecht nicht eingetragen";
    const height = dancer?.height_cm ? `${dancer.height_cm} cm` : "Größe nicht eingetragen";
    return `${dancer?.name || "Unbekannt"} · ${gender} · ${height}`;
  }

  function getExternalEligibleWorkshops() {
    return (workshops || [])
      .filter(w => w.allow_partner_search !== false)
      .filter(w => !w.starts_at || new Date(w.starts_at) >= new Date())
      .sort((a, b) => {
        const da = a.starts_at ? new Date(a.starts_at).getTime() : Number.MAX_SAFE_INTEGER;
        const db = b.starts_at ? new Date(b.starts_at).getTime() : Number.MAX_SAFE_INTEGER;
        return da - db;
      });
  }

  function externalWorkshopDateTime(w) {
    const date = w.starts_at ? formatDate(w.starts_at) : (w.recurrence_text || "Termin offen");
    const time = w.start_time ? String(w.start_time).slice(0, 5) : (w.starts_at ? formatTime(w.starts_at) : "");
    return `${date}${time ? ` · ${time} Uhr` : ""}`;
  }

  function openExternalPrintWindow(title, bodyHtml, css) {
    // Druckdialog direkt aus der Benutzeraktion öffnen. Android/Chrome kann
    // window.print() blockieren, wenn es erst nach einem setTimeout ausgeführt wird.
    // Deshalb wird hier kein verzögertes print() verwendet.
    const frame = document.createElement("iframe");
    frame.style.position = "fixed";
    frame.style.left = "-10000px";
    frame.style.top = "0";
    frame.style.width = "794px";
    frame.style.height = "1123px";
    frame.style.border = "0";
    frame.style.background = "white";
    frame.setAttribute("aria-hidden", "true");
    document.body.appendChild(frame);

    const doc = frame.contentDocument || frame.contentWindow?.document;
    if (!doc || !frame.contentWindow) {
      frame.remove();
      alert("Die Druckansicht konnte nicht erstellt werden.");
      return;
    }

    doc.open();
    doc.write(`<!doctype html><html lang="de"><head><meta charset="utf-8"><title>${esc(title)}</title><style>${css}</style></head><body>${bodyHtml}</body></html>`);
    doc.close();

    // Wichtig: print() unmittelbar aus dem Klick-Handler heraus aufrufen.
    // Kein setTimeout / kein onload, damit Chrome die Benutzeraktion erkennt.
    try {
      frame.contentWindow.focus();
      frame.contentWindow.print();
    } catch (err) {
      frame.remove();
      alert("Der Druckdialog konnte nicht geöffnet werden. Bitte erneut auf Drucken tippen.");
      return;
    }

    // Das iframe erst nach dem Druckversuch entfernen. Bei manchen Browsern
    // wird der Dialog synchron geöffnet, bei anderen kurz danach.
    setTimeout(() => {
      if (document.body.contains(frame)) frame.remove();
    }, 3000);
  }

  function createExternalDancerPdfBlob(blankList = false) {
    if (!externalDancers.length) return null;

    const safe = value => String(value ?? "")
      .replace(/[\r\n]+/g, " ")
      .replace(/[“”„‟]/g, '"')
      .replace(/[‘’‚‛]/g, "'")
      .replace(/[–—]/g, "-")
      .replace(/…/g, "...")
      .replace(/·/g, "-")
      .replace(/[^\x00-\xFF]/g, "?");
    const escPdf = value => safe(value)
      .replace(/\\/g, "\\\\")
      .replace(/\(/g, "\\(")
      .replace(/\)/g, "\\)");

    const PAGE_W = 595, PAGE_H = 842, LEFT = 42, RIGHT = 553, TOP = 795, BOTTOM = 42;
    const pages = [];
    let commands = [];
    let y = TOP;

    const newPage = () => {
      if (commands.length) pages.push(commands);
      commands = [];
      y = TOP;
    };
    const ensure = h => { if (y - h < BOTTOM) newPage(); };
    const drawText = (x, yy, value, size = 14, bold = false) => {
      commands.push(`BT /${bold ? "F2" : "F1"} ${size} Tf 1 0 0 1 ${x} ${yy} Tm (${escPdf(value)}) Tj ET`);
    };
    const line = (x1, y1, x2, y2) => commands.push(`0.7 w ${x1} ${y1} m ${x2} ${y2} l S`);
    const wrap = (value, maxChars = 70) => {
      const words = safe(value).split(/\s+/).filter(Boolean);
      const lines = [];
      let current = "";
      words.forEach(word => {
        const next = current ? `${current} ${word}` : word;
        if (next.length > maxChars && current) { lines.push(current); current = word; }
        else current = next;
      });
      if (current) lines.push(current);
      return lines.length ? lines : [""];
    };

    drawText(LEFT, y, blankList ? "Blankoliste - externe Taenzer" : "Externe Taenzer - Verfuegbarkeiten", 20, true);
    y -= 28;
    drawText(LEFT, y, blankList
      ? "Alle zukuenftigen Workshops mit aktivierter Tanzpartnersuche"
      : "Vorgemerkte Taenzer mit ihren vorgemerkten Workshop-Terminen", 14);
    y -= 26;
    line(LEFT, y, RIGHT, y);
    y -= 18;

    const eligible = getExternalEligibleWorkshops();
    externalDancers.forEach((dancer, dancerIndex) => {
      const available = blankList
        ? eligible
        : eligible.filter(w => externalAvailability.some(a =>
            String(a.external_dancer_id) === String(dancer.id) &&
            Number(a.workshop_id) === Number(w.id) &&
            (a.status === "available" || a.status === "assigned")
          ));

      ensure(75);
      drawText(LEFT, y, `${dancerIndex + 1}. ${safe(dancer.name || "Externer Taenzer")}`, 16, true);
      y -= 19;
      const contact = [dancer.phone ? `Telefon: ${dancer.phone}` : "", dancer.email ? `E-Mail: ${dancer.email}` : ""].filter(Boolean).join("   ");
      if (contact) { drawText(LEFT + 10, y, contact, 14); y -= 18; }
      if (dancer.notes) { drawText(LEFT + 10, y, `Bemerkung: ${safe(dancer.notes)}`, 14); y -= 18; }

      if (!available.length) {
        ensure(28);
        drawText(LEFT + 10, y, blankList ? "Keine zukuenftigen Workshops vorhanden." : "Keine vorgemerkten Workshop-Termine.", 14);
        y -= 20;
      } else {
        available.forEach(w => {
          const date = w.starts_at ? formatDate(w.starts_at) : (w.recurrence_text || "Termin offen");
          const time = w.start_time ? String(w.start_time).slice(0, 5) : (w.starts_at ? formatTime(w.starts_at) : "");
          const title = safe(w.title || "Workshop");
          const status = externalAvailability.find(a =>
            String(a.external_dancer_id) === String(dancer.id) && Number(a.workshop_id) === Number(w.id)
          )?.status === "assigned" ? " - vermittelt" : "";
          const rowLines = wrap(`${date}${time ? ` - ${time} Uhr` : ""} - ${title}${w.level ? ` - ${w.level}` : ""}${status}`, 72);
          ensure(20 * rowLines.length + 5);
          rowLines.forEach((row, idx) => { drawText(LEFT + 10, y, `${idx === 0 ? "- " : "  "}${row}`, 14); y -= 18; });
        });
      }
      y -= 6;
      line(LEFT, y, RIGHT, y);
      y -= 16;
    });

    if (commands.length) pages.push(commands);

    const objects = [];
    const pageIds = [];
    const contentIds = [];
    objects.push("<< /Type /Catalog /Pages 2 0 R >>");
    objects.push("");
    pages.forEach(cmds => {
      const stream = cmds.join("\n");
      contentIds.push(objects.length + 1);
      objects.push(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);
      pageIds.push(objects.length + 1);
      objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PAGE_W} ${PAGE_H}] /Resources << /Font << /F1 0 0 R /F2 0 0 R >> >> /Contents ${contentIds[contentIds.length - 1]} 0 R >>`);
    });
    const font1Id = objects.length + 1;
    objects.push("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
    const font2Id = objects.length + 1;
    objects.push("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");
    pages.forEach((_, index) => {
      const objIndex = pageIds[index] - 1;
      objects[objIndex] = `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PAGE_W} ${PAGE_H}] /Resources << /Font << /F1 ${font1Id} 0 R /F2 ${font2Id} 0 R >> >> /Contents ${contentIds[index]} 0 R >>`;
    });
    objects[1] = `<< /Type /Pages /Kids [${pageIds.map(id => `${id} 0 R`).join(" ")}] /Count ${pageIds.length} >>`;

    let pdf = "%PDF-1.4\n%\xE2\xE3\xCF\xD3\n";
    const offsets = [0];
    objects.forEach((obj, index) => {
      offsets[index + 1] = pdf.length;
      pdf += `${index + 1} 0 obj\n${obj}\nendobj\n`;
    });
    const xrefOffset = pdf.length;
    pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
    for (let i = 1; i <= objects.length; i++) pdf += `${String(offsets[i]).padStart(10, "0")} 00000 n \n`;
    pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;

    const bytes = new Uint8Array(pdf.length);
    for (let i = 0; i < pdf.length; i++) bytes[i] = pdf.charCodeAt(i) & 0xFF;
    return new Blob([bytes], { type: "application/pdf" });
  }

  function createExternalDancerByDatePdfBlob() {
    if (!externalDancers.length) return null;

    const safe = value => String(value ?? "")
      .replace(/[\r\n]+/g, " ")
      .replace(/[“”„‟]/g, '"')
      .replace(/[‘’‚‛]/g, "'")
      .replace(/[–—]/g, "-")
      .replace(/…/g, "...")
      .replace(/·/g, "-")
      .replace(/[^\x00-\xFF]/g, "?");
    const escPdf = value => safe(value)
      .replace(/\\/g, "\\\\")
      .replace(/\(/g, "\\(")
      .replace(/\)/g, "\\)");

    const PAGE_W = 595, PAGE_H = 842, LEFT = 42, RIGHT = 553, TOP = 795, BOTTOM = 42;
    const pages = [];
    let commands = [];
    let y = TOP;
    const newPage = () => {
      if (commands.length) pages.push(commands);
      commands = [];
      y = TOP;
    };
    const ensure = h => { if (y - h < BOTTOM) newPage(); };
    const drawText = (x, yy, value, size = 14, bold = false) => {
      commands.push(`BT /${bold ? "F2" : "F1"} ${size} Tf 1 0 0 1 ${x} ${yy} Tm (${escPdf(value)}) Tj ET`);
    };
    const line = (x1, y1, x2, y2) => commands.push(`0.7 w ${x1} ${y1} m ${x2} ${y2} l S`);
    const wrap = (value, maxChars = 70) => {
      const words = safe(value).split(/\s+/).filter(Boolean);
      const lines = [];
      let current = "";
      words.forEach(word => {
        const next = current ? `${current} ${word}` : word;
        if (next.length > maxChars && current) { lines.push(current); current = word; }
        else current = next;
      });
      if (current) lines.push(current);
      return lines.length ? lines : [""];
    };

    drawText(LEFT, y, "Externe Taenzer - Liste nach Datum", 20, true);
    y -= 28;
    drawText(LEFT, y, "Workshop-Termine mit den jeweils vorgemerkten externen Taenzern", 14);
    y -= 26;
    line(LEFT, y, RIGHT, y);
    y -= 20;

    const eligible = getExternalEligibleWorkshops();
    const groups = new Map();

    eligible.forEach(w => {
      const dancers = externalDancers.filter(d => externalAvailability.some(a =>
        String(a.external_dancer_id) === String(d.id) &&
        Number(a.workshop_id) === Number(w.id) &&
        (a.status === "available" || a.status === "assigned")
      ));
      if (!dancers.length) return;

      const key = `${w.starts_at || w.id}`;
      if (!groups.has(key)) groups.set(key, { workshop: w, dancers: [] });
      groups.get(key).dancers.push(...dancers);
    });

    const sortedGroups = [...groups.values()].sort((a,b) => {
      const ta = a.workshop?.starts_at ? new Date(a.workshop.starts_at).getTime() : Number(a.workshop?.id || 0);
      const tb = b.workshop?.starts_at ? new Date(b.workshop.starts_at).getTime() : Number(b.workshop?.id || 0);
      return ta - tb;
    });

    sortedGroups.forEach(group => {
      const w = group.workshop;
      const date = w.starts_at ? formatDate(w.starts_at) : (w.recurrence_text || "Termin offen");
      const time = w.start_time ? String(w.start_time).slice(0,5) : (w.starts_at ? formatTime(w.starts_at) : "");
      const title = safe(w.title || "Workshop");
      const uniqueDancers = [...new Map(group.dancers.map(d => [String(d.id), d])).values()];
      ensure(70);
      drawText(LEFT, y, `${date}${time ? ` - ${time} Uhr` : ""}`, 17, true);
      y -= 21;
      wrap(title, 66).forEach((row, idx) => {
        drawText(LEFT + 8, y, `${idx === 0 ? "" : "  "}${row}`, 14, idx === 0);
        y -= 17;
      });
      uniqueDancers.forEach(d => {
        const assigned = externalAvailability.some(a =>
          String(a.external_dancer_id) === String(d.id) &&
          Number(a.workshop_id) === Number(w.id) &&
          a.status === "assigned"
        );
        ensure(20);
        drawText(LEFT + 18, y, `- ${safe(d.name || "Externer Taenzer")}${assigned ? " - vermittelt" : " - verfuegbar"}`, 14);
        y -= 18;
      });
      y -= 5;
      line(LEFT, y, RIGHT, y);
      y -= 15;
    });

    if (!sortedGroups.length) {
      drawText(LEFT, y, "Keine vorgemerkten externen Taenzer fuer zukuenftige Workshops.", 14);
    }

    if (commands.length) pages.push(commands);

    const objects = [];
    const pageIds = [];
    const contentIds = [];
    objects.push("<< /Type /Catalog /Pages 2 0 R >>");
    objects.push("");
    pages.forEach(cmds => {
      const stream = cmds.join("\n");
      contentIds.push(objects.length + 1);
      objects.push(`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`);
      pageIds.push(objects.length + 1);
      objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PAGE_W} ${PAGE_H}] /Resources << /Font << /F1 0 0 R /F2 0 0 R >> >> /Contents ${contentIds[contentIds.length - 1]} 0 R >>`);
    });
    const font1Id = objects.length + 1;
    objects.push("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
    const font2Id = objects.length + 1;
    objects.push("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");
    pages.forEach((_, index) => {
      const objIndex = pageIds[index] - 1;
      objects[objIndex] = `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PAGE_W} ${PAGE_H}] /Resources << /Font << /F1 ${font1Id} 0 R /F2 ${font2Id} 0 R >> >> /Contents ${contentIds[index]} 0 R >>`;
    });
    objects[1] = `<< /Type /Pages /Kids [${pageIds.map(id => `${id} 0 R`).join(" ")}] /Count ${pageIds.length} >>`;

    let pdf = "%PDF-1.4\n%\xE2\xE3\xCF\xD3\n";
    const offsets = [0];
    objects.forEach((obj, index) => {
      offsets[index + 1] = pdf.length;
      pdf += `${index + 1} 0 obj\n${obj}\nendobj\n`;
    });
    const xrefOffset = pdf.length;
    pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
    for (let i = 1; i <= objects.length; i++) pdf += `${String(offsets[i]).padStart(10, "0")} 00000 n \n`;
    pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;

    const bytes = new Uint8Array(pdf.length);
    for (let i = 0; i < pdf.length; i++) bytes[i] = pdf.charCodeAt(i) & 0xFF;
    return new Blob([bytes], { type: "application/pdf" });
  }

  async function createAndShareExternalDancerByDatePdf() {
    const blob = createExternalDancerByDatePdfBlob();
    if (!blob) { alert("Es sind noch keine Gastherren vorgemerkt."); return; }
    const file = new File([blob], "Externe-Taenzer-nach-Datum.pdf", { type: "application/pdf" });
    try {
      if (navigator.share && (!navigator.canShare || navigator.canShare({ files: [file] }))) {
        await navigator.share({
          title: "Gastherren nach Datum",
          text: "Gastherren sortiert nach Workshop-Datum",
          files: [file]
        });
        return;
      }
    } catch (error) {
      if (error?.name === "AbortError") return;
    }
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = file.name;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 2000);
  }

