      return `<section class="dancer"><h2>${esc(dancer.name || "Gastherr")}</h2><div class="data">Telefon: ${esc(dancer.phone || "")} &nbsp;&nbsp; E-Mail: ${esc(dancer.email || "")}</div>${dancer.notes ? `<div class="data">Bemerkung: ${esc(dancer.notes)}</div>` : ""}<table><thead><tr><th>Datum / Uhrzeit</th><th>Workshop</th><th>Verfügbarkeit</th><th>Notiz</th></tr></thead><tbody>${rows}</tbody></table></section>`;
